setup_input.go:*guideTerminal.start:
func() {
	defer close(e.done)
	queue := t.pending
	t.pending = nil
	enqueue := func(event tea.Msg) {
		if key, ok := event.(uv.KeyPressEvent); ok && tea.KeyPressMsg(key).String() == "ctrl+c" {
			t.stop()
			return
		}
		queue = append(queue, event)
	}
	for {
		var send chan tea.Msg
		var first tea.Msg
		if len(queue) > 0 {
			send = e.events
			first = queue[0]
		}
		select {
		case event := <-decoded:
			enqueue(event)
		case send <- first:
			queue[0] = nil
			queue = queue[1:]
		case <-parsed:
			t.stop()

			<-e.stop
			reader.close()
			cancel()
			t.pending = queue
			return
		case <-e.stop:
			reader.finish()

			for {
				select {
				case event := <-decoded:
					enqueue(event)
				case <-parsed:
					reader.close()
					cancel()
					t.pending = queue
					return
				}
			}
		}
	}
}

